// ib_points_min where the official document states one and the row has none.
const POINTS = {
  "ru-biology": "27",
  "ru-chemistry": "27",
  "ru-cs": "27",
  "ru-mls": "27",
  "ru-natsci": "27",
};

// ------------------------------------------------------------------- write

if (!head.includes('ib_maths')) {
  const at = head.indexOf('ib_subjects') + 1;
  head.splice(at, 0, 'ib_maths');
  for (const r of rows) r.splice(at, 0, '');
}
const col = (name) => { const i = head.indexOf(name); if (i < 0) throw new Error(`no column ${name}`); return i; };
const [iId, iSubj, iMaths, iPts, iVer] = ['programme_id', 'ib_subjects', 'ib_maths', 'ib_points_min', 'last_verified'].map(col);
const byId = new Map(rows.map((r) => [r[iId], r]));

const checkMaths = (id, m) => {
  if (m === 'none' || m === '?') return;
  const bad = m.split(' · ').filter((c) => !COURSES.includes(c));
  if (bad.length) throw new Error(`${id}: bad ib_maths ${m}`);
};

let wrote = 0;
for (const [id, [subjects, maths, source]] of Object.entries(NEW)) {
  const r = byId.get(id);
  if (!r) throw new Error(`unknown programme ${id}`);
  if (!source) throw new Error(`${id}: no source`);
  checkMaths(id, maths);
  const text = subjects.copy ? byId.get(subjects.copy)[iSubj] : subjects;
  if (!text) throw new Error(`${id}: nothing to copy from ${subjects.copy}`);
  if (r[iSubj] && r[iSubj] !== text) throw new Error(`${id}: ib_subjects already says "${r[iSubj]}"`);
  r[iSubj] = text; r[iMaths] = maths; r[iVer] = TODAY; wrote++;
}
for (const [id, [subjects, maths, source]] of Object.entries(REWRITE)) {
  const r = byId.get(id);
  if (!r || !source) throw new Error(`REWRITE ${id}`);
  checkMaths(id, maths);
  r[iSubj] = subjects; r[iMaths] = maths; r[iVer] = TODAY; wrote++;
}
for (const [id, maths] of Object.entries(MATHS_ONLY)) {
  const r = byId.get(id);
  if (!r || !r[iSubj]) throw new Error(`MATHS_ONLY ${id}`);
  checkMaths(id, maths);
  r[iMaths] = maths;
}
for (const [id, pts] of Object.entries(POINTS)) {
  const r = byId.get(id);
  if (!r[iPts]) r[iPts] = pts;
}
writeFileSync(url, [head, ...rows].map((r) => r.map(esc).join(',')).join('\n') + '\n');
const blank = rows.filter((r) => !r[iSubj]).map((r) => r[iId]);
console.log(`ib_subjects written for ${wrote} rows; ib_maths set on ${rows.filter((r) => r[iMaths]).length} of ${rows.length}`);
console.log(`still blank (${blank.length}): ${blank.join(', ')}`);
